<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Category;use App\Models\Service;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Str;
class ServiceController extends Controller{public function index(){return view('admin.services.index',['services'=>Service::with(['category','provider'])->latest()->paginate(15),'categories'=>Category::orderBy('name')->get(),'providers'=>User::where('role','provider')->where('is_active',true)->orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['category_id'=>'required|exists:categories,id','provider_id'=>'required|exists:users,id','name'=>'required|max:150','description'=>'nullable|max:3000','price'=>'required|numeric|min:1','duration'=>'required|max:50']);$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));Service::create($d);return back()->with('success','Service created.');}public function update(Request $r,Service $service){$d=$r->validate(['category_id'=>'required|exists:categories,id','name'=>'required|max:150','description'=>'nullable|max:3000','price'=>'required|numeric|min:1','duration'=>'required|max:50','is_active'=>'nullable|boolean']);$service->update($d);return back()->with('success','Service updated.');}public function destroy(Service $service){$service->delete();return back()->with('success','Service deleted.');}}
